import{_ as t,o,c as a,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const _=JSON.parse('{"title":"2011年 · 坚守价值","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2011年.md","filePath":"05_quotes/by-year/2011年.md"}'),r={name:"05_quotes/by-year/2011年.md"};function u(c,e,s,q,b,i){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_2011年-·-坚守价值" tabindex="-1">2011年 · 坚守价值 <a class="header-anchor" href="#_2011年-·-坚守价值" aria-label="Permalink to &quot;2011年 · 坚守价值&quot;">​</a></h1><blockquote><p>投资是现在放弃消费，以便在以后有能力消费更多。——巴菲特（81岁）</p></blockquote><p>本页收录2011年致股东信中的经典语录。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>投资者应如何看待股价波动：重要的不是你看到什么，而是你看见什么。</p></blockquote><blockquote><p>那些未来将成为净买家的人，看到股价上涨时感到安慰——这就像一位通勤者仅仅因为油箱里有一天的油储备，就在油价上涨时欢呼雀跃。</p></blockquote><blockquote><p>一个免税机构需要在过去47年间从债券投资中获得4.3%的年利率才能维持购买力。</p></blockquote><blockquote><p>隐形的通货膨胀&quot;税&quot;是我们投资者可能认为是其主要负担的显所得税的三倍多。</p></blockquote><blockquote><p>黄金有两个重大缺陷：既不太有用也不能生育。</p></blockquote><blockquote><p>如果你拥有一盎司黄金直到永恒，你在其结束时仍然只拥有一盎司。</p></blockquote><blockquote><p>17万吨黄金将大小不变，仍然不能生产任何东西。你可以抚摸这个立方体，但它不会回应。</p></blockquote><blockquote><p>一个世纪后，4亿英亩的农田将生产惊人的玉米、小麦、棉花和其他作物——并将继续生产这种有价值的赏金，无论货币是什么。</p></blockquote><blockquote><p>智者在一开始做的，愚者在最后做。</p></blockquote><blockquote><p>我们国家的企业将继续高效地交付我们公民想要的商品和服务。这些商业&quot;奶牛&quot;将活几个世纪，并产出越来越多的&quot;牛奶&quot;。</p></blockquote><blockquote><p>1776年以来，美国最好的日子还在前方。</p></blockquote><blockquote><p>我们的目标是找到一匹2岁的Secretariat，而不是一匹10岁的Seabiscuit。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2011年，伯克希尔哈撒韦每股账面价值增长4.6%，连续九年实现承保盈利。巴菲特在信中深入阐述了他的投资哲学，将投资定义为&quot;现在放弃消费，以便在以后有能力消费更多&quot;。他将黄金等无生产力资产与农田、企业等生产性资产进行对比，强调生产性资产是长期最优选择。同年收购路博润（Lubrizol），并新增IBM和美国银行的大额投资。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2011年-翻译-·-01-letters-2011年-核心总结-·-01-letters-2011年-思维导图" tabindex="-1"><a href="/01_letters/2011年/翻译">01_letters/2011年/翻译</a> · <a href="/01_letters/2011年/核心总结">01_letters/2011年/核心总结</a> · <a href="/01_letters/2011年/思维导图">01_letters/2011年/思维导图</a> <a class="header-anchor" href="#_01-letters-2011年-翻译-·-01-letters-2011年-核心总结-·-01-letters-2011年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2011年/翻译]] · [[→ 核心总结|01_letters/2011年/核心总结]] · [[→ 思维导图|01_letters/2011年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2011年/翻译">/01_letters/2011年/翻译</a></li></ul>',25)])])}const h=t(r,[["render",u]]);export{_ as __pageData,h as default};
